def incr(self, key, delta=1, version=None):
    key = self.make_key(key, version)
    with self._lock:
        if key in self._cache:
            self._cache[key] = self._cache[key] + delta
            return self._cache[key]
        else:
            raise ValueError("Key '%s' not found" % key)
